mapper.select:
select generation_id, generation_code, generation_mode, input_amount, target_amount, generation_status, generation_remark, generated_count, started_time, finished_time, user_id, client_request_id, worker_id, lease_expire_time, attempt_count, max_attempts, next_retry_time, result_source, manual_import_by, manual_import_time, data_as_of, ai_scene_code, ai_contract_version, ai_plan_run_ref, ai_analysis_run_ref, ai_evidence_status, ai_evidence_error, create_by, create_time, update_by, update_time from fx67ll_dortmund_return_generation
and generation_id = #{generationId}
and generation_status = #{generationStatus}
and generation_mode = #{generationMode} and result_source = #{resultSource} and user_id = #{userId}
and create_time between #{beginCreateTime} and #{endCreateTime}
order by create_time desc, generation_id desc

mapper.update:
update fx67ll_dortmund_return_generation
set ai_plan_input_snapshot = #{planInputSnapshot},
    update_time = now()
where generation_id = #{generationId}
  and worker_id = #{workerId}
  and generation_status = '0'

update fx67ll_dortmund_return_generation
set ai_analysis_input_snapshot = #{analysisInputSnapshot},
    update_time = now()
where generation_id = #{generationId}
  and worker_id = #{workerId}
  and generation_status = '0'

mapper.select:
select count(1)
from fx67ll_dortmund_return_generation
where generation_id = #{generationId}
  and worker_id = #{workerId}
  and generation_status = '0'
